class Solution {
    private int best = 0;

    public int maxProfit(int[] prices) {
        dfs(prices, 0, false, 0);
        return best;
    }

    private void dfs(int[] prices, int day, boolean hold, int profit) {
        if (day == prices.length) {
            best = Math.max(best, profit);
            return;
        }
        dfs(prices, day + 1, hold, profit);
        if (!hold) dfs(prices, day + 1, true, profit - prices[day]);
        else dfs(prices, day + 1, false, profit + prices[day]);
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int profit = 0;
        for (int i = 1; i < prices.length; i++) {
            if (prices[i] > prices[i - 1]) {
                profit += prices[i] - prices[i - 1];
            }
        }
        return profit;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        if (prices.length == 0) return 0;
        int hold = -prices[0];
        int free = 0;

        for (int i = 1; i < prices.length; i++) {
            int p = prices[i];
            int newHold = Math.max(hold, free - p);
            int newFree = Math.max(free, hold + p);
            hold = newHold;
            free = newFree;
        }
        return free;
    }
}
